import{_ as t,o as a,c as o,aw as i}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Информация","description":"","frontmatter":{},"headers":[],"relativePath":"framework-react/next-js/fetch/info.md","filePath":"wiki/dev-commit/framework-react/next-js/fetch/info.md"}'),r={name:"framework-react/next-js/fetch/info.md"};function c(l,e,n,s,h,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h1><h2 id="информация-1" tabindex="-1">Информация <a class="header-anchor" href="#информация-1" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><ul><li>В компоненте можно использовать стандартный Fetch для запросов на сервер. Но, в этом случае, запросы будут отправляться со стороны клиента в runtime. Если посмотреть исходный код страницы, то данных из API не будет.</li><li>Задача в том, чтобы поисковые роботы могли индексировать данные с сервера.</li><li>Для этого на сервере необходимо сделать запрос и вернуть уже страницу с добавленными данными.</li><li>Next.js вместо браузерного Fetch использует пакет <em>isomorphic-unfetch</em> <a href="https://github.com/developit/unfetch" target="_blank" rel="noreferrer">https://github.com/developit/unfetch</a></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>С версии 9.4 Next.js сам предоставляет <code>fetch()</code> и на сервере, и в браузере: пакеты <code>isomorphic-unfetch</code> и <code>node-fetch</code> не нужны</li></ul></div>',4)])])}const u=t(r,[["render",c]]);export{m as __pageData,u as default};
